      p++
      const e = expr()
      if (!isOp(')')) throw new Bad()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { type: 'call', name: t.v.toUpperCase(), args } }
