      const a = parseAddr(n.w)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const x = evalNode(n.x)
      if (x.t === 'err') return x
      const v = toNum(x)
      if (v.t === 'err') return v
      return n.op === '-' ? num(-v.n) : v
