#!/usr/bin/env node
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'err', e })
const num = (n) => ({ t: 'num', n })

function colIndex(letters) {
  const u = letters.toUpperCase()
  if (u.length === 1) return u.charCodeAt(0) - 64
  return 26 + (u.charCodeAt(0) - 65) * 26 + (u.charCodeAt(1) - 64)
}
function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1]), row }
}
const key = (c, r) => c * 1000 + r
const addrStr = (c, r) => colName(c) + r

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const word = /^[^ \t]*/.exec(s)[0]
  const rest = s.slice(word.length).replace(/^[ \t]+/, '')
  const a = parseAddr(word)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${word}\n`)
    process.exit(2)
  }
  const k = key(a.col, a.row)
  if (cells.has(k)) {
    process.stderr.write(`error: line ${i + 1}: cell ${word.toUpperCase()} is declared twice\n`)
    process.exit(2)
  }
  cells.set(k, { col: a.col, row: a.row, content: rest })
}

class Bad extends Error {}
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ k: 'op', v: two }); i += 2; continue }
    if ('+-*/^()=<>,:'.includes(c)) { toks.push({ k: 'op', v: c }); i++; continue }
    throw new Bad()
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  let misplaced = false

  function range(first) {
    p++
    const t = toks[p]
    if (!t || t.k !== 'word') throw new Bad()
    p++
    return { type: 'range', a: first, b: t.v }
  }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'un', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.k === 'num') { p++; return { type: 'num', n: t.v } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw new Bad()
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        const name = t.v.toUpperCase()
        if (isOp(')')) { p++; return { type: 'call', name, args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw new Bad()
        }
        return { type: 'call', name, args }
      }
      if (isOp(':')) { misplaced = true; return range(t.v) }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { type: 'bool', b: true }
      if (u === 'FALSE') return { type: 'bool', b: false }
      return { type: 'ref', w: t.v }
    }
    throw new Bad()
  }
  function arg() {
    const t = toks[p]
    if (t && t.k === 'word' && toks[p + 1] && toks[p + 1].k === 'op' && toks[p + 1].v === ':') {
      const save = p
      p++
      const r = range(t.v)
      if (isOp(',') || isOp(')')) return r
      p = save
    }
    return cmp()
  }
  const ast = cmp()
  if (p < toks.length) throw new Bad()
  return { ast, misplaced }
}

function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push([c, r])
  return out
}

function collectDeps(n, set) {
  if (n.type === 'ref') {
    const a = parseAddr(n.w)
    if (a) set.add(key(a.col, a.row))
  } else if (n.type === 'range') {
    const cs = rangeCells(n.a, n.b)
    if (cs) for (const [c, r] of cs) set.add(key(c, r))
  } else if (n.type === 'bin') { collectDeps(n.l, set); collectDeps(n.r, set) }
  else if (n.type === 'un') collectDeps(n.x, set)
  else if (n.type === 'call') for (const a of n.args) collectDeps(a, set)
}

const parsed = new Map()
function getParsed(k, content) {
  if (!parsed.has(k)) {
    let r
    try { r = parseFormula(content.slice(1)) } catch (e) { if (e instanceof Bad) r = null; else throw e }
    parsed.set(k, r)
  }
  return parsed.get(k)
}

const memo = new Map()
const busy = new Set()
function cellValue(c, r) {
  const k = key(c, r)
  if (memo.has(k)) return memo.get(k)
  const cell = cells.get(k)
  if (!cell) return num(0)
  if (busy.has(k)) return err('#CYCLE!')
  busy.add(k)
  let v
  const content = cell.content
  if (content[0] === '=') {
    const p = getParsed(k, content)
    if (!p || p.misplaced) v = err('#ERR!')
    else v = evalNode(p.ast)
  } else if (content === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) v = num(Number(content))
  else if (ERRS.includes(content)) v = err(content)
  else v = { t: 'text', s: content }
  busy.delete(k)
  memo.set(k, v)
  return v
}

function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.b ? 1 : 0)
  if (v.t === 'text') return err('#VALUE!')
  return v
}
const fin = (n) => (Number.isFinite(n) ? num(n) : err('#DIV/0!'))

function cmpCode(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { num: 0, text: 1, bool: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'num') return a.n < b.n ? -1 : a.n > b.n ? 1 : 0
  if (a.t === 'text') return cmpCode(a.s, b.s)
  return (a.b ? 1 : 0) - (b.b ? 1 : 0)
}

function evalNode(n) {
  switch (n.type) {
    case 'num': return fin(n.n)
    case 'bool': return { t: 'bool', b: n.b }
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const x = evalNode(n.x)
      if (x.t === 'err') return x
      const v = toNum(x)
      if (v.t === 'err') return v
      return n.op === '-' ? num(-v.n) : v
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (l.t === 'err') return l
      const r = evalNode(n.r)
      if (r.t === 'err') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const b = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { t: 'bool', b }
      }
      const a = toNum(l)
      if (a.t === 'err') return a
      const b = toNum(r)
      if (b.t === 'err') return b
      switch (n.op) {
        case '+': return fin(a.n + b.n)
        case '-': return fin(a.n - b.n)
        case '*': return fin(a.n * b.n)
        case '/': return b.n === 0 ? err('#DIV/0!') : fin(a.n / b.n)
        case '^': return fin(Math.pow(a.n, b.n))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const name = n.name
  const args = n.args
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    if (args.some((a) => a.type === 'range')) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'err') return c
    let truth
    if (c.t === 'bool') truth = c.b
    else if (c.t === 'num') truth = c.n !== 0
    else return err('#VALUE!')
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    if (args[0].type === 'range') return err('#ERR!')
    const x = evalNode(args[0])
    if (x.t === 'err') return x
    const v = toNum(x)
    if (v.t === 'err') return v
    return num(Math.abs(v.n))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.type === 'range') {
      const cs = rangeCells(a.a, a.b)
      if (!cs) { vals.push(err('#REF!')); continue }
      for (const [c, r] of cs) vals.push(cellValue(c, r))
    } else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.t === 'err')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
  const ns = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'err') return x
    ns.push(x.n)
  }
  switch (name) {
    case 'SUM': return fin(ns.reduce((s, x) => s + x, 0))
    case 'AVG': return fin(ns.reduce((s, x) => s + x, 0) / ns.length)
    case 'MIN': return fin(ns.reduce((s, x) => Math.min(s, x)))
    case 'MAX': return fin(ns.reduce((s, x) => Math.max(s, x)))
  }
  return err('#ERR!')
}

function fmt(v) {
  switch (v.t) {
    case 'num': return String(Number(v.n.toPrecision(10)))
    case 'err': return v.e
    case 'bool': return v.b ? 'TRUE' : 'FALSE'
    default: return v.s
  }
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
for (const c of sorted) {
  const a = addrStr(c.col, c.row)
  if (mode === 'values') out += `${a}=${fmt(cellValue(c.col, c.row))}\n`
  else {
    let line = `${a}:`
    if (c.content[0] === '=') {
      const p = getParsed(key(c.col, c.row), c.content)
      if (p) {
        const set = new Set()
        collectDeps(p.ast, set)
        for (const k of [...set].sort((x, y) => x - y)) line += ' ' + addrStr(Math.floor(k / 1000), k % 1000)
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
